INSERT INTO source SELECT id,url,publisher,title,kind,'2026-11-23',NULL,NULL FROM cited;
INSERT INTO event VALUES
('lotto_inception','operator','operations','confirmed','국민은행 운영으로 로또 6/45 개시','판매 개시일과 첫 추첨일은 다르다. 운영 주체와 추첨기 변경을 별개로 기록한다.',NULL,'2002-12-02','2002-12-02','day'),
('lotto_live_10','broadcast','announcement','confirmed','SBS 제10회 생방송 예고','SBS 당일 8뉴스에서 해당 회차의 생방송을 예고했다. 이 자료만으로 이후 전 회차가 계속 생방송이었다고 볼 수 없다.','2003-02-08','2003-02-08','2003-02-08','day'),
('lotto_regular_live','broadcast','announcement','unresolved','정례 생방송 전환 발표','2003년 8월 보도는 10월 전환 계획을 전한다. 실제 첫 적용 회차와 제10회 이후 생방송 연속 여부는 확인하지 못했다. 기간은 발표상 목표 월이다.','2003-08-22','2003-10-01','2003-10-31','month'),
('lotto_1000','rules','operations','confirmed','판매가 및 5등 고정 당첨금 인하','88회 판매분부터 게임당 2,000원에서 1,000원, 5등 지급액 10,000원에서 5,000원. 번호 일치 규칙 자체의 변경은 아니다.','2004-07-21','2004-08-01','2004-08-01','day'),
('lotto_nanum','operator','operations','confirmed','국민은행에서 나눔로또로 인계','운영은 12월 2일 전환, 262회 당첨금부터 농협중앙회 지급. 종전 회차는 기존 지급처 유지.',NULL,'2007-12-02','2007-12-02','day'),
('lotto_venus','equipment','mechanism','confirmed','할로겐 회전식에서 비너스 공기혼합식으로 교체','262회부터 새 장비. 옛 공 약 78g, 새 공 약 4g. 신형 재질은 사후 방송 자료의 폴리우레탄을 따른다. 사전 보도의 셀룰로이드 표기와 다르다.',NULL,'2007-12-08','2007-12-08','day'),
('lotto_fixed4','rules','operations','confirmed','4등 당첨금 5만원 정액제','401회부터 4등 정액 지급 및 판매점 수령. 날짜는 공식 회차 결과의 401회 추첨일.',NULL,'2010-08-07','2010-08-07','day'),
('p520_start','rules','mechanism','confirmed','연금복권520 첫 추첨','7개 조의 인쇄식 연금복권. 1등 월 500만원을 20년 지급; 한국연합복권이 운영. 초기 추첨에 화살과 회전판이 사용되었고 YTN이 수요일에 방송했다.','2011-07-05','2011-07-06','2011-07-06','day'),
('lotto_backup461','equipment','mechanism','reported','461회 예비 장비로 대체','추첨 중 장비 이상으로 예비 추첨 절차가 적용되었다는 당시 보도. 일회성 사건으로 분류한다.',NULL,'2011-10-01','2011-10-01','day'),
('p520_mbn','broadcast','operations','reported','연금복권520 YTN에서 MBN으로 이동','27회 경계는 편성 연표에 의존한다. 2012년 11월 동시대 보도는 JTBC 이동 직전 방송사가 MBN임을 확인한다.',NULL,'2012-01-04','2012-01-04','day'),
('p520_tier5','rules','mechanism','confirmed','연금복권520 5등 일치 자리 수 변경','66회부터 끝 4자리 일치·20만원에서 끝 3자리 일치·2만원으로 바뀌었다. 두 시기의 결과 패턴을 있는 그대로 보존한다.',NULL,'2012-10-03','2012-10-03','day'),
('p520_jtbc','broadcast','operations','confirmed','연금복권520 MBN에서 JTBC로 이동','75회부터 JTBC. 발표된 편성은 수요일 오후 7시 30분이며 방송사 변경과 함께 스튜디오와 방청 방식 변경이 공지되었다.',NULL,'2012-12-05','2012-12-05','day'),
('common_nanum3','operator','operations','confirmed','나눔로또 제3기 사업 및 통합 수탁','로또 수탁자는 유지되고 연금복권은 한국연합복권에서 나눔로또로 이동한다. 국산 온라인복권 시스템 도입은 계약 단계에 공지되었다.','2013-09-03','2013-12-02','2013-12-02','day'),
('common_portal','publication','operations','reported','로또·연금복권 결과를 한 포털로 통합','통합 수탁 전 시범 운영에서 두 상품의 결과를 함께 조회할 수 있었다는 보도.','2013-11-24','2013-11-17','2013-11-17','day'),
('lotto_backup636','equipment','mechanism','reported','636회 예비 추첨기·공 세트 사용','당시 보도와 당시 공지 전재에서 본추첨 중 예비 장비 사용 확인. 영구 교체로 해석하지 않는다.',NULL,'2015-02-07','2015-02-07','day'),
('p520_sbsplus','broadcast','operations','confirmed','연금복권520 JTBC에서 SBS플러스로 이동','240회부터 SBS플러스에서 수요일 오후 7시 40분경 생방송. 운영사 발표에 따르면 직전의 방송 시각은 유지되었다.','2016-01-28','2016-02-03','2016-02-03','day'),
('lotto_venus_rl2','equipment','mechanism','reported','비너스 RL2 도입 보도','733회부터 공기 혼합식 신형 비너스를 사용했다는 당시 보도. 이후 르포의 교체 횟수와 표현이 상충하며 볼 세트 교체 여부는 미확인이다.',NULL,'2016-12-17','2016-12-17','day'),
('common_dh4','operator','operations','confirmed','나눔로또에서 동행복권 제4기로 인계','2018년 12월 2일 업무 이전. 로또 836회, 연금복권520 388회가 인계 후 첫 추첨이다.','2018-11-26','2018-12-02','2018-12-02','day'),
('lotto_pc','rules','operations','confirmed','로또 PC 인터넷 구매 시작','판매 채널 및 결과 조회 홈페이지가 바뀌었으며 번호 추첨 규칙 변경을 뜻하지 않는다.','2018-11-26','2018-12-02','2018-12-02','day'),
('p520_mbcdrama','broadcast','operations','confirmed','연금복권520 SBS플러스에서 MBC드라마넷으로 이동','388회부터 MBC드라마 채널. 전환 당시 안내 시각은 수요일 저녁 7시 30분경이다.','2018-11-26','2018-12-05','2018-12-05','day'),
('lotto_mbc','broadcast','operations','confirmed','로또 SBS에서 MBC로 이동','836회부터 MBC 저녁 8시 45분 편성; 황금손 코너를 신설했다. 당시 판매 마감은 그대로였다.','2018-12-03','2018-12-08','2018-12-08','day'),
('p720_sales','rules','operations','confirmed','연금복권720+ 판매 전환','복권위원회 공지상 정식 출시일. 판매점 일부에는 준비를 위해 먼저 공급했다. 직전 520의 마지막 추첨은 4월 29일이다.','2020-04-20','2020-04-30','2020-04-30','day'),
('p720_rules','rules','mechanism','confirmed','연금복권720+ 첫 추첨 및 당첨 구조 개편','520에서 720+로 상품과 회차가 분리된다. 7개 조에서 5개 조, 본추첨과 보너스, 1등 월 700만원·20년, 2등과 보너스 월 100만원·10년.','2020-04-20','2020-05-07','2020-05-07','day'),
('p720_topaze','equipment','mechanism','confirmed','화살·회전판에서 Topaze 추첨기로 전환','520의 화살 추첨에서 720+의 공 추첨 장비로 전환. 개별 장비·볼 로트별 투입 날짜를 의미하지 않는다.',NULL,'2020-05-07','2020-05-07','day'),
('p720_mbc','broadcast','operations','confirmed','연금복권 지상파 MBC 목요일 추첨','720+ 제1회부터 목요일 MBC 지상파. 출시 자료의 정오 편성은 현재 편성과 같지 않으며 이동 날짜는 확인되지 않았다.',NULL,'2020-05-07','2020-05-07','day'),
('lotto_audit','oversight','observation','reported','TTA와 서울대 통계연구소의 외부 검증','보도에 따르면 두 기관이 각각 운영·추첨 절차, 결과의 통계적 동등성을 검토했다. 검증 자체를 추첨 절차의 변경으로 보지 않는다.',NULL,'2023-04-01','2023-06-30','range'),
('lotto_open1071','oversight','observation','confirmed','1071회 대국민 공개 생방송','일반 시민 150명과 기자단이 공개 참관. 영구적 방식 변경으로 분류하지 않는다.',NULL,'2023-06-10','2023-06-10','day'),
('common_dh5','operator','operations','confirmed','동행복권 제5기 위탁 개시','사업자 자체는 유지되며 계약 기간은 2024-01-01~2028-12-31이다. 추첨기 교체의 근거는 아니다.','2023-05-03','2024-01-01','2024-01-01','day'),
('lotto_open1147','oversight','observation','confirmed','1147회 2024 로터리데이','일반인 약 100명의 공개 추첨 참관 행사. 영구적 방식 변경으로 분류하지 않는다.',NULL,'2024-11-23','2024-11-23','day'),
('lotto_mobile','rules','operations','confirmed','스마트폰 웹 로또 판매 시범 도입','평일 모바일 웹 판매 개시, PC·모바일 합산 구매 한도 적용. 발표는 하반기 확대 계획도 언급했으나 이 행은 시범 운영 시작만 나타낸다.','2026-02-06','2026-02-09','2026-02-09','day'),
('lotto_web2026','publication','observation','reported','결과 페이지의 공개 조회 경로 변경','2026년 개편 뒤 화면 내 JSON 경로가 바뀌었음을 재현했다. 개편 시행일과 최초 적용 회차는 확인되지 않았고 물리적 추첨 변경이 아니다.',NULL,'2026-01-01','2026-11-23','range'),
('ball_lot_history','equipment','observation','unresolved','개별 장비·볼 세트 투입 이력 미확인','공개 자료만으로 전체 회차의 실제 본추첨기 일련번호, 세트 교체, 정비일을 확인하지 못했다. 사용 개체가 동일하다고 가정하지 않는다.',NULL,NULL,NULL,'unknown');
